// import 'jasmine'; (google3-only)
import {sendKeys} from '@web/test-runner-commands';
import {html, render, type ReactiveElement, type TemplateResult} from 'lit';
import './md-gb-split-button.js';
import '../menu/md-gb-menu.js';
import '../menu/md-gb-menu-item.js';

let container: HTMLElement | undefined;

async function mount(template: TemplateResult) {
  container?.remove();
  container = document.createElement('div');
  document.body.appendChild(container);
  render(template, container);
  await settle();
  return container;
}

/** Waits for Lit updates and a frame. */
async function settle(root: ParentNode = document.body) {
  for (const el of root.querySelectorAll('*')) {
    const update = (el as Partial<ReactiveElement>).updateComplete;
    if (update) await update;
    if (el.shadowRoot) await settle(el.shadowRoot);
  }
  if (root !== document.body) return;
  await new Promise((resolve) => requestAnimationFrame(resolve));
}

/** Presses a key (or a chord such as `Shift+Tab`) on a real keyboard. */
async function press(key: string) {
  await sendKeys({press: key});
  await settle();
}

import {sendMouse} from '@web/test-runner-commands';
import {adoptStyles} from '../../styles/adopt-styles.js';
import {styles as m3Styles} from '../../styles/m3.cssresult.js';

adoptStyles(document, [m3Styles]);

/** Waits for the surface's open animation (its size and place are final after). */
async function finishAnimations(el: Element) {
  const animations = el.getAnimations({subtree: true});
  await Promise.all(animations.map((a): Promise<unknown> => a.finished.catch((): void => {})));
}

/** The focused element, looking inside shadow roots. */
function deepActive(): Element | null {
  let el = document.activeElement;
  while (el?.shadowRoot?.activeElement) el = el.shadowRoot.activeElement;
  return el;
}

async function setupAnchored0(opts: {edge?: 'top' | 'bottom' | 'end'} = {}) {
  const style = {
    bottom: 'bottom: 4px; left: 60px',
    top: 'top: 4px; left: 60px',
    end: 'top: 200px; right: 2px',
    none: 'top: 200px; left: 60px',
  }[opts.edge ?? 'none'];
  const root = await mount(html`
    <div style="position: fixed; ${style}">
      <md-gb-split-button>
        <button slot="leading">Save</button>
        <button slot="trailing" id="invoker" aria-label="More actions" popovertarget="menu"></button>
        <md-gb-menu id="menu">
        <md-gb-menu-item>One</md-gb-menu-item>
        <md-gb-menu-item>Two</md-gb-menu-item>
        <md-gb-menu-item>Three</md-gb-menu-item>
        </md-gb-menu>
      </md-gb-split-button>
    </div>
  `);
  const f = {
    root,
    get invoker() {
      return root.querySelector<HTMLElement>('#invoker')!;
    },
    get anchor() {
      return root.querySelector<HTMLElement>('#invoker')!;
    },
    get surface() {
      return root.querySelector<HTMLElement>('md-gb-menu')!;
    },
  };
  return f;
}

describe('<md-gb-split-button> anchored overlay contract (AnchoredOverlayController: popover, below, flip, light dismiss, focus return)', () => {
  afterEach(() => container?.remove());

  it('opens as a popover in the top layer, below its invoker, end-aligned', async () => {
    // spec: split-button-fab8df, split-button-65d4ae, split-button-347947, split-button-54f72d, menus-66cea9
    const f = await setupAnchored0();
    f.invoker.click();
    await settle();
    await finishAnimations(f.surface);
    expect(f.surface.matches(':popover-open')).toBeTrue();
    expect(f.surface.hasAttribute('popover')).toBeTrue();
    const a = f.anchor.getBoundingClientRect();
    const s = f.surface.getBoundingClientRect();
    expect(s.top).toBeGreaterThanOrEqual(a.bottom - 0.5);
    expect(Math.abs(s.top - a.bottom - 4)).toBeLessThan(1.5);
    expect(Math.abs(s.right - a.right)).toBeLessThan(1.5);
  });

  it('flips to the above when there is no room below', async () => {
    // spec: split-button-394dbb, split-button-24bec6, split-button-4e0abb
    const f = await setupAnchored0({edge: 'bottom'});
    f.invoker.click();
    await settle();
    await finishAnimations(f.surface);
    expect(f.surface.matches(':popover-open')).toBeTrue();
    const a = f.anchor.getBoundingClientRect();
    const s = f.surface.getBoundingClientRect();
    expect(s.bottom).toBeLessThanOrEqual(a.top + 0.5);
    expect(Math.abs(a.top - s.bottom - 4)).toBeLessThan(1.5);
    expect(s.top).toBeGreaterThanOrEqual(-0.5);
    expect(s.bottom).toBeLessThanOrEqual(window.innerHeight + 0.5);
  });

  it('stays inside the window at its inline end', async () => {
    // spec: split-button-4e0abb, menus-74a090
    const f = await setupAnchored0({edge: 'end'});
    f.invoker.click();
    await settle();
    await finishAnimations(f.surface);
    expect(f.surface.matches(':popover-open')).toBeTrue();
    const s = f.surface.getBoundingClientRect();
    expect(s.left).toBeGreaterThanOrEqual(-0.5);
    expect(s.right).toBeLessThanOrEqual(document.documentElement.clientWidth + 0.5);
  });

  it('closes with Escape', async () => {
    // spec: menus-235f42
    const f = await setupAnchored0();
    f.invoker.click();
    await settle();
    await finishAnimations(f.surface);
    expect(f.surface.matches(':popover-open')).toBeTrue();
    await press('Escape');
    expect(f.surface.matches(':popover-open')).toBeFalse();
  });

  it('closes with a press outside', async () => {
    // spec: menus-509021
    const f = await setupAnchored0();
    f.invoker.click();
    await settle();
    await finishAnimations(f.surface);
    expect(f.surface.matches(':popover-open')).toBeTrue();
    await sendMouse({type: 'click', position: [document.documentElement.clientWidth - 6, 6]});
    await settle();
    expect(f.surface.matches(':popover-open')).toBeFalse();
  });

  it('returns focus to the invoker when it was inside', async () => {
    // spec: split-button-227d99
    const f = await setupAnchored0();
    f.invoker.focus();
  await press('Enter');
    await settle();
    expect(f.surface.matches(':popover-open')).toBeTrue();
    expect(deepActive()).not.toBe(f.invoker);
    await press('Escape');
    expect(f.surface.matches(':popover-open')).toBeFalse();
    expect(deepActive()).toBe(f.invoker);
  });
});
